import { describe, it, expect } from "vitest";
import { createChaseCamera } from "./chase-camera.ts";

const n = (v: { x: number; y: number; z: number }) => { const l = Math.hypot(v.x, v.y, v.z); return { x: v.x / l, y: v.y / l, z: v.z / l }; };
const dot = (a: any, b: any) => a.x * b.x + a.y * b.y + a.z * b.z;
const axes = (cam: any) => {
    const m = cam.worldMatrix as any;
    return {
        x: { x: m[0], y: m[1], z: m[2] },
        y: { x: m[4], y: m[5], z: m[6] },
        z: { x: m[8], y: m[9], z: m[10] },
        eye: { x: m[12], y: m[13], z: m[14] },
    };
};

describe("chase camera", () => {
    const eye = { x: 0, y: 2, z: -10 };
    const target = { x: 0, y: 1, z: 5 };
    const fwd = n({ x: target.x - eye.x, y: target.y - eye.y, z: target.z - eye.z });

    it("starts upright and looks at target", () => {
        const { camera } = createChaseCamera(eye, target);
        const a = axes(camera);
        expect(dot(a.y, { x: 0, y: 1, z: 0 })).toBeGreaterThan(0.999);
        expect(dot(a.z, fwd)).toBeGreaterThan(0.999999);
        expect(a.eye).toEqual({ x: eye.x, y: eye.y, z: eye.z });
    });

    it("rolls picture-up to the projection of the car up", () => {
        const c = createChaseCamera(eye, target);
        const up = n({ x: 0.6, y: 0.5, z: 0.2 });
        c.bank(up);
        const a = axes(c.camera);
        const expected = n({ x: up.x - fwd.x * dot(up, fwd), y: up.y - fwd.y * dot(up, fwd), z: up.z - fwd.z * dot(up, fwd) });
        expect(dot(a.y, expected)).toBeGreaterThan(0.999999);
        expect(dot(a.z, fwd)).toBeGreaterThan(0.999999);
        expect(Math.abs(dot(a.x, fwd))).toBeLessThan(1e-9);
    });

    it("keeps previous roll when up is parallel to line of sight, either way", () => {
        const c = createChaseCamera(eye, target);
        const up = n({ x: 0.6, y: 0.5, z: 0.2 });
        c.bank(up);
        const before = axes(c.camera);
        c.bank(fwd);
        c.bank({ x: -fwd.x, y: -fwd.y, z: -fwd.z });
        const after = axes(c.camera);
        for (const k of ["x", "y", "z", "eye"] as const) {
            expect(after[k].x).toBeCloseTo(before[k].x, 12);
            expect(after[k].y).toBeCloseTo(before[k].y, 12);
            expect(after[k].z).toBeCloseTo(before[k].z, 12);
        }
    });

    it("degenerate call on fresh camera keeps upright", () => {
        const c = createChaseCamera(eye, target);
        const start = axes(c.camera);
        c.bank(fwd);
        const after = axes(c.camera);
        expect(dot(after.y, start.y)).toBeGreaterThan(0.999999);
    });

    it("handles vertical view with upright fallback", () => {
        const c = createChaseCamera({ x: 0, y: 10, z: 0 }, { x: 0, y: 0, z: 0 });
        const a = axes(c.camera);
        expect(Number.isFinite(a.y.y)).toBe(true);
        expect(Math.hypot(a.y.x, a.y.y, a.y.z)).toBeGreaterThan(0.999);
    });
});
